#include <iostream>
#include <fstream>
#include <string>
#include <map>
using namespace std;

int main() {
    ifstream f1("produkty.txt");
    int id;
    string nazwa, kategoria;
    map<int, string> katProduktu;
    while (f1 >> id >> nazwa >> kategoria) {
        katProduktu[id] = kategoria;
    }
    ifstream f2("sprzedaz.txt");
    int idProd, ilosc;
    map<int, int> sumaProd;
    while (f2 >> idProd >> ilosc) {
        sumaProd[idProd] += ilosc;
    }
    map<string, int> perKat;
    int powyzej5 = 0;
    for (auto& s : sumaProd) {
        perKat[katProduktu[s.first]] += s.second;
        if (s.second > 5) powyzej5++;
    }
    cout << "Sprzedaz per kategoria:" << endl;
    string bestKat;
    int bestVal = 0;
    for (auto& p : perKat) {
        cout << "   " << p.first << ": " << p.second << endl;
        if (p.second > bestVal) {
            bestVal = p.second;
            bestKat = p.first;
        }
    }
    cout << "Produkty sprzedane wiecej niz 5 sztuk: " << powyzej5 << endl;
    cout << "Kategoria z najwyzsza sprzedaza: " << bestKat << " (" << bestVal << ")" << endl;
    return 0;
}
```

